operation.add:
if ($this->customer->isLogged()) {
					$data['confirm_recipient'] = trim($order_data['firstname'] . ' ' . $order_data['lastname']);
					$data['confirm_contact']   = (!empty($order_data['telephone']) ? $order_data['telephone'] . ' · ' : '') . $order_data['email'];
				} elseif (isset($this->session->data['evrika_registrant'])) {
					$_reg = $this->session->data['evrika_registrant'];
					$data['confirm_recipient'] = trim($_reg['firstname'] . ' ' . $_reg['lastname']);
					$data['confirm_contact']   = (!empty($_reg['telephone']) ? $_reg['telephone'] . ' · ' : '') . $_reg['email'];
				} else {
					$data['confirm_recipient'] = '';
					$data['confirm_contact']   = '';
				}
				$data['confirm_shipping'] = isset($this->session->data['shipping_method']['title']) ? $this->session->data['shipping_method']['title'] : '';
				$data['confirm_payment']  = isset($this->session->data['payment_method']['title'])  ? $this->session->data['payment_method']['title']  : '';
				$data['confirm_store_address'] = $this->config->get('config_address');
				$_shipping_code = isset($this->session->data['shipping_method']['code']) ? strtolower($this->session->data['shipping_method']['code']) : '';
				$data['confirm_is_pickup'] = (strpos($_shipping_code, 'pickup') !== false);
				// Адрес доставки (для не-самовывоза)
				$_sa = isset($this->session->data['shipping_address']) ? $this->session->data['shipping_address'] : array();
				$_addr_parts = array_filter(array(
					isset($_sa['postcode']) && $_sa['postcode'] ? $_sa['postcode'] : '',
					isset($_sa['city'])     && $_sa['city']     ? $_sa['city']     : '',
					isset($_sa['address_1'])&& $_sa['address_1']? $_sa['address_1']: '',
				));
				$data['confirm_shipping_address'] = implode(', ', $_addr_parts);
				// Подпись способа оплаты
				$_pay_code = isset($this->session->data['payment_method']['code']) ? $this->session->data['payment_method']['code'] : '';
				if ($_pay_code === 'bank_transfer') {
					$data['confirm_payment_sub'] = 'Счёт на оплату будет отправлен на email';
				} elseif ($_pay_code === 'cod') {
					$data['confirm_payment_sub'] = 'Наличный расчёт и оплата картой';
				} else {
					$data['confirm_payment_sub'] = '';
				}
				$data['payment_code'] = $_pay_code;
